INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('万', 'wàn', '一', '3', '一结构', '⒈   万（萬）wàn   ⒈数目字十千为一～。', '勹');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('丈', 'zhànɡ', '一', '3', '一结构', '⒈市制长度单位。十尺是一～。', '乂');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('三', 'sān', '一', '3', '一结构', '⒈数目字～个。～人行必有我师。', '二');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('上', 'shànɡ', '一', '3', '一结构', '⒈位置在高处的，跟"下"相对～面。', '丨+一');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('下', 'xià', '一', '3', '一结构', '⒈位置在低处，跟"上"相对～部。', '卜');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('不', 'bù', '一', '4', '一结构', '   用在动词、形容词或个别副词前,表示否定    医之好治不病以为功。', '丿+丨+丶');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('与', 'yǔ', '一', '3', '一结构', '⒈跟，同，和～众不同。～虎谋皮。我～你们一道走。', '㇉+一');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('专', 'zhuān', '一', '4', '二结构', '⒈独，独有，独占～断。～利。～权。～制。独断～行。', '丨+龴');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('且', 'qiě', '一', '5', '月结构', '⒉见qiě。   且qiě   ⒈连词。〈表〉进一层～说。而～。并～。况～。既多...', '一');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('世', 'shì', '一', '5', '廿结构', '⒈一生，一辈子人生一～。只有今生今～，既无前～，也无来～。', '丨+一');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('丘', 'qiū', '丿', '5', '厂结构', '⒈土堆，小山土～。～陵。', '工');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('业', 'yè', '业', '5', '丨结构', '⒈事情，所从事的工作事～。创～。功～。', '丨+丷+一');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('丛', 'cónɡ', '一', '5', '从结构', '   同本义    丛,聚也。', '一');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('东', 'dōnɡ', '一', '5', '一结构', '   同本义    东,动也。', '𠃋+小');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('丝', 'sī', '一', '5', '丝结构', '⒈蚕吐出的纤维。它是绸、缎等的原料新～。', '丝');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('丞', 'chénɡ', '一', '6', '氶结构', '⒈辅助～相（宰相。辅助君王，他是君王属下的最高官吏）。', '一');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('丢', 'diu1', '一', '6', '丿结构', '丢失;遗失    抛弃;撇开    用眼色暗示    搁置 ', '去');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('两', 'liǎng', NULL, NULL, '一结构', NULL, '冂+丨+人+人');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('严', 'yán', '一', '7', '亚结构', '⒈紧密，没有缝隙～密。将瓶口封～。', '丿');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('丧', 'sànɡ', '一', '8', '土结构', '⒈失掉，死亡～失。～胆。～命。', '丷+□');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('个', 'ɡè', '丨', '3', '人结构', '⒈单，独～人。～别。～体。', '丨');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('中', 'zhōnɡ', '丨', '4', '口结构', '⒈符合，适合，正着，正对上～意。圆者～规，方者～矩。正～下怀。打～目标。百发百～...', '丨');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('丰', 'fēnɡ', '丨', '4', '丿结构', '⒈豷） fēng   ⒈富，盛，多，大 ～盛。～硕。～富多彩。～衣足食。～功伟绩...', '二+丨');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('串', 'chuàn', '丨', '7', '口结构', '⒈连贯，连贯成行的贯～。～珠儿。', '口+丨');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('临', 'lín', '丨', '9', '丨结构', '⒈从高处往低处看居高～下（形容不可阻挡的形势）。', '丨+丿+一+丶+口+丨');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('丸', 'wán', '丿', '3', '丶结构', '⒈小而圆的东西泥～。弹～儿。鱼～。肉～子。', '九');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('丹', 'dān', '丶', '4', '冂结构', '2米以上， 羽毛白色； 翅大， 末端黑色，能高飞；头顶皮肤裸露，呈朱红色。', '丶+一');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('为', 'wéi', '丶', '4', '丶结构', '⒈做，干事在人～。敢作敢～。', '丿+㇆+丶');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('主', 'zhǔ', '丶', '5', '丶结构', '⒈最重要的，最基本的，事物的根本～力。～食。～流。～题。～要矛盾。预防为～。', '王');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('丽', 'lì', '丶', '7', '一结构', '⒉   丽（麗）lì   ⒈漂亮，好看～人。太美～。非常壮～。风和日～。', '冂+丶+冂+丶');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('举', 'jǔ', '丶', '9', '兴结构', '⒈抬起，向上托～头。', '二+丨');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('乃', 'nǎi', '丿', '2', '丿结构', '⒈你，你的～父。～弟。', '㇆+㇆');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('久', 'jiǔ', '丿', '3', '丿结构', '⒈时间长天长日～。～经考验。～别重逢。', '入');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('么', 'me', '丿', '3', '丿结构', '⒈用于词尾什～？怎～？这～∶～。', '厶');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('义', 'yì', '丶', '3', '丶结构', '⒈公正合宜的道德、道理或行为正～。～愤填膺。～正辞严。见～勇为。多行不～，必自毙...', '乂');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('之', 'zhī', '丿', '3', '独体结构', '⒈到，往由京～川。不知所～。', '');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('乌', 'wū', '丿', '4', '勹结构', '⒉黑色～衣。～云。～烟。', '㇉+一');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('乎', 'hū', '丿', '5', '丿结构', '⒈文言助词。〈表〉疑问或反问，相当于"吗"、"呢"、"吧"可～？然～？否～？或能...', '丷+一+亅');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('乏', 'fá', '丿', '4', '丿结构', '⒈缺少缺～粮食。太～味。不～其人。', '之');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('乐', 'lè', '丿', '5', '丿结构', '⒈快活，高兴快～。欢～。～事。～不可支。', '丨+木');
