INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('凡', 'fán', '几', '3', '几结构', '⒈所有的，总共，总计～是。～事。～六月。', '丶');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('凤', 'fènɡ', '几', '4', '几结构', '   同本义    凤,神鸟也。', '又');
