INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('切', 'qiē', '刀', '4', '七结构', '⒈割开，截断～开。～猪肉。～断敌军退路。', '刀');
