INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('划', 'huá', '刂', '6', '戈结构', '⒈用尖锐的东西把别的物体分割开～玻璃。～西瓜。〈引〉破裂这苹果～了一条口。霹雳闪...', '刀');
