INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('力', 'lì', '力', '2', '丿结构', '⒈能量，效能～量。～气。视～。电～。能～。效～。生产～。身强～壮。', '㇆');
