INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('励', 'lì', '力', '7', '厉结构', '   同本义    勵,勉力也。', '力');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('劲', 'jìn', '力', '7', '圣结构', '⒈正直，挺拔，坚强有力～士。～松。～草。良将～旅。', '力');
