INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('势', 'shì', '力', '8', '埶结构', '⒈力量，权力，威力～力。有权有～。人多～众。', '力+勢');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('勃', 'bó', '力', '9', '孛结构', '0米。', '力');
