INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('勤', 'qín', '力', '13', '堇结构', '⒈努力，尽力，跟"懒"相对～快。～奋。～学苦练。～俭节约。～劳致富。', '力');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('勺', 'sháo', '勹', '3', '勹结构', '⒈一种有柄的可舀取东西的用具汤～。饭～子。木～子。钢～儿。', '丶');
