INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('匀', 'yún', '勹', '4', '勹结构', '⒈平均，使平均均～。谷种要撒～。两盘菜～一～，就一样多了。', '冰');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('包', 'bāo', '勹', '5', '勹结构', '1.通"庖"。', '己');
