INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('匠', 'jiànɡ', '匚', '6', '匚结构', '⒈泛指有专门手艺的工人木～。铁～。泥水～。能工巧～。', '斤');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('匣', 'xiá', '匚', '7', '匚结构', '⒈装东西的器具，通常指小型而有开合盖的木～子。铁～子。', '甲');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('匪', 'fěi', '匚', '10', '匚结构', '⒈盗贼，抢劫财物的坏人～徒。～帮。追捕惯～。严惩车～路霸。', '非');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('匹', 'pǐ', '匚', '4', '匸结构', '⒈相当，相等，相配～敌。～配（又指婚姻）。', '儿');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('区', 'qū', '匚', '4', '匸结构', '⒈姓。   区（區）qū   ⒈分别～分。～别。', '乂');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('医', 'yī', '匚', '7', '匚结构', '⒈治病～疗。～治。', '矢');
