INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('千', 'qiān', '十', '3', '丿结构', '5家为社,千社为25000家);千祀(千年,千代);总数为一千;千乘(兵车千辆)...', '十');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('升', 'shēnɡ', '十', '4', '千结构', '0毫升,合一市升。', '丨');
