INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('单', 'dān', '十', '8', '丷结构', '单于 chan      月黑雁飞高,单于夜遁逃。', '甲+一');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('卖', 'mài', '十', '8', '十结构', '⒈用东西换货币，跟"买"相反～粮。～棉。～鸡蛋。', '买');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('南', 'nán', '十', '9', '十结构', '1.见"南无"。', '冂+丫+二');
