INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('占', 'zhàn', '卜', '5', '卜结构', '⒈据有，夺取～据。～有。～领。攻～。', '口');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('卡', 'kǎ', '卜', '5', '上结构', '⒈卡车，又简称"卡"大～车。十轮～。', '卜');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('卫', 'wèi', '卩', '3', '卩结构', '⒈保护，防护～国。保～。自～。防～。', '一');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('印', 'yìn', '卩', '5', '卬结构', '⒈图章，戳记～章。校～。盖～。～把子（也〈喻〉政权）。', '一');
