INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('慢', 'màn', '忄', '14', '心结构', '⒈迟缓，跟"快"相对缓～。～走。～性病。～吞吞。', '曼');
