INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('戒', 'jiè', '戈', '7', '廾结构', '⒈防备～备。～心常存。', '戈');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('或', 'huò', '戈', '8', '口结构', '⒈也许。〈表〉不肯定，选择～许。～者。～近～远。～多～少。这个～那个。', '一+戈');
