INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('戴', 'dài', '戈', '17', '十结构', '8年12月当选法兰西第五共和国总统，奉行独立自主的外交政策，促使法国于1964年...', '戈+異');
