INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('收', 'shōu', '攵', '6', '丩结构', '⒈接到，接受，接纳～到。～留。～入。～款。～容。接～。招～。征～。不～礼。', '攴');
