INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('攻', 'ɡōnɡ', '攵', '7', '工结构', '⒈进击，打击，跟"守"相对～击。进～。反～。～城略地（略掠夺）。～其不备。', '攴');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('放', 'fànɡ', '攵', '8', '方结构', '⒈解脱约束，获得自由解～。', '攴');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('政', 'zhènɡ', '攵', '9', '正结构', '⒈政治，它是经济的集中表现。', '攴');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('故', 'ɡù', '攵', '9', '古结构', '⒈旧，过去的，跟"新"相对～旧。会见～人（故人老朋友）。回到～居。', '攴');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('效', 'xiào', '攵', '10', '交结构', '⒈成果，功用～果。成～。有～。', '攴');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('敌', 'dí', '攵', '10', '舌结构', '   同本义    敌,仇也。', '攴');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('敏', 'mǐn', '攵', '11', '每结构', '⒈聪明，机智，迅速，反应快～锐。～捷。～感。灵～。～而好学。', '攴');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('救', 'jiù', '攵', '11', '求结构', '⒈帮助，援助，使脱离困境或危险～济。～援。～急。急～。拯～。患难相～。遇良医可～...', '攴');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('教', 'jiào', '攵', '11', '孝结构', '⒈指导，培育，培养～导。～养。～诲。请～。因材施～。～学相长。', '攴');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('敛', 'liǎn', '攵', '11', '佥结构', '⒈收，聚集收～。聚～。秋～冬藏。〈引〉征收横征暴～。', '攴');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('敝', 'bì', '攵', '11', '丷结构', '同本义    敝,一曰败衣。', '巾+八+攴');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('敞', 'chǎnɡ', '攵', '12', '尚结构', '⒈宽阔，高朗～亮。～丽。宽～。轩～。', '攴');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('敢', 'ɡǎn', '攵', '11', '丅结构', '⒈有勇气，有胆量勇～。～说真话。～于担重任。', '耳+攴');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('散', 'sàn', '攵', '12', '井结构', '⒈零碎的，零星的～装。～兵游勇。', '月+攴');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('敬', 'jìnɡ', '攵', '12', '茍结构', '⒈尊重，热爱，仰慕，佩服尊～。～业。～爱。～仰。～慕。～佩。', '攴');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('数', 'shù', '攵', '13', '娄结构', '⒈屡次，经常频～。', '攴');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('敲', 'qiāo', '攴', '14', '高结构', '⒈击，打～门。～锣。～边鼓（〈喻〉从旁帮人说话）。', '攴');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('整', 'zhěnɡ', '攵', '16', '敕结构', '⒈不乱，有秩序～齐。～洁。', '正');
