INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('料', 'liào', '斗', '10', '米结构', '⒈估计，猜想～想。预～。～事如神。', '斗');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('斜', 'xié', '斗', '11', '余结构', '⒈歪，不正～视。～坡。倾～。', '斗');
