INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('斧', 'fǔ', '斤', '8', '父结构', '⒈砍东西用的工具～头。把～子拿来。', '斤');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('斩', 'zhǎn', '斤', '8', '车结构', '1.沾。', '斤');
