INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('斯', 'sī', '斤', '12', '其结构', '⒈指示代词。此，这个，这里～人。～时。如～。至于～。', '斤');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('新', 'xīn', '斤', '13', '亲结构', '⒈初出现或初产生的～生。～事物。～技术。', '斤');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('方', 'fānɡ', '方', '4', '亠结构', '⒈四角都是直角的四边形或每个面都是直角四边形的六面体正～形。长～形。立～体。', '勹');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('施', 'shī', '方', '9', '方结构', '⒈实行，展示，发挥～行。～展。～工。把本领～出来。', '丿+一+也');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('旁', 'pánɡ', '方', '10', '亠结构', '⒈边，侧～边。两～。～观者清。', '丷+冖+方');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('旅', 'lǚ', '方', '10', '方结构', '⒈出行，在外作客～行。～途。～客。～居。～馆。', '丿+一+氏');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('旋', 'xuán', '方', '11', '方结构', '⒈转动，弯转～转。盘～。螺～。', '丿+一+疋');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('族', 'zú', '方', '11', '方结构', '⒈有一定血统关系的人群之总称家～。宗～。', '丿+一+矢');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('旗', 'qí', '方', '14', '方结构', '⒈用布、绸、纸等做成的标帜，多为长方形或方形～子。军～。国～。升～。', '丿+一+其');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('无', 'wú', '无', '4', '一结构', '⒈没有，跟"有"相对～粮～钱。～穷～尽。', '尢');
