INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('旦', 'dàn', '日', '5', '日结构', '0米长的纤维重量为多少克，它的纤度就是多少旦。', '一');
