INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('烈', 'liè', '灬', '10', '列结构', '⒈猛，厉害猛～。强～。～火。～酒。', '火');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('烘', 'hōnɡ', '火', '10', '火结构', '⒈烤干、烤热或向火取暖～衣服。～面包。～火。', '共');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('烛', 'zhú', '火', '10', '火结构', '⒈以线绳或苇子做中心，周围用蜡和油脂包裹，点燃取光的东西蜡～成灰泪始干。', '虫');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('烟', 'yān', '火', '10', '火结构', '⒈物质燃烧时所产生的气状物～雾。煤～。油～儿。', '因');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('烤', 'kǎo', '火', '10', '火结构', '⒈用火把东西烘干或烘熟～烟。～鸭。', '考');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('烦', 'fán', '火', '10', '火结构', '⒈急躁，苦闷～躁。～闷。心～。莫～恼。', '页');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('烧', 'shāo', '火', '10', '火结构', '⒈使物体着火～ 火。燃～。', '尧');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('烫', 'tànɡ', '火', '10', '汤结构', '⒈皮肤接触温度高的东西感到疼痛或损伤水太～。～伤。', '火');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('烬', 'jìn', '火', '10', '火结构', '⒈火烧物体之后剩下的东西灰～。烛～。', '尽');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('热', 'rè', '灬', '10', '执结构', '⒈物理学上指凡能使物体温度升高的那种"能"叫"热"。', '火');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('焦', 'jiāo', '灬', '12', '隹结构', '⒈物体经火烧变成炭样饭～了。～头烂额（头被火烧成重伤。〈喻〉十分窘迫难堪）。', '火');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('焰', 'yàn', '火', '12', '火结构', '⒈火苗火～。〈喻〉气势气～。', '臽');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('然', 'rán', '灬', '12', '肉结构', '⒈是，对以为～。', '犬+火');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('煌', 'huánɡ', '火', '13', '火结构', '⒈明亮辉～的灯火。明星～ ～。', '皇');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('煤', 'méi', '火', '13', '火结构', '⒈也叫"煤炭"或"石炭"。', '某');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('照', 'zhào', '灬', '13', '日结构', '⒈光线射着～射。～耀。特指日光夕～。', '召+火');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('熄', 'xī', '火', '14', '火结构', '   同本义    熄,畜火也。', '息');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('熊', 'xiónɡ', '灬', '14', '能结构', '⒈属国家保护的哺乳动物，严禁猎杀食用。', '火');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('熟', 'shú', '灬', '15', '孰结构', '⒈烹饪食物达到可吃程度～食。肉～了。～透了。', '火');
