INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('燃', 'rán', '火', '16', '火结构', '⒈烧～烧。～料。自～。助～。', '然');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('燕', 'yàn', '灬', '16', '廿结构', '⒈燕子，翼尖而长，尾巴叉状像张开的剪刀。', '北+口+火');
