INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('爆', 'bào', '火', '19', '火结构', '    同本义     爆,灼也。', '暴');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('爪', 'zhǎo', '爪', '4', '厂结构', '⒈指甲或趾甲手～。', '丨+乀');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('爬', 'pá', '爪', '8', '爪结构', '⒈上下肢伏地行走，虫类、爬行动物等的行走～着走。不吃苍蝇～过的食物。龟在慢慢地～...', '巴');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('父', 'fù', '父', '4', '八结构', '⒈对老年人的尊称农夫渔～。', '乂');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('爷', 'yé', '父', '6', '父结构', '⒊对同辈或年长男人的敬称老大～。李大～。', '卩');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('爸', 'bà', '父', '8', '父结构', '1.即父亲。', '巴');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('爽', 'shuǎnɡ', '爻', '11', '大结构', '⒈明朗，清亮～朗。清～。秋高气～。', '爻+爻');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('片', 'piàn', '片', '4', '丄结构', '⒈破开的木或草木～。竹～。麦草～。〈引〉扁而薄的东西名～。铁～子。明信～儿。', '丿+㇆');
