INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('牌', 'pái', '片', '12', '片结构', '⒈用作标志、凭信物等的板招～。门～。寄车～子。', '卑');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('牙', 'yá', '牙', '4', '丅结构', '⒈指牙齿门～。', '一+亅+丿');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('牛', 'niú', '牛', '4', '丿结构', '⒈家畜，反刍类动物。', '一+十');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('牢', 'láo', '牛', '7', '宀结构', '⒈饲养牲畜的栏圈亡羊补～（〈喻〉事后及时补救）。', '牛');
