INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('犁', 'lí', '牛', '11', '利结构', '⒈耕地的农具，用畜力或拖拉机等牵引。', '牛');
