INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('状', 'zhuànɡ', '犬', '7', '丬结构', '⒈样子，形态，情形～态。～况。形～。喜笑～。重病～。', '犬');
