INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('玻', 'bō', '王', '9', '玉结构', '0年起投身南美独立战争，曾获''解放者''称号，多次   率军打败西班牙军队。', '皮');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('珍', 'zhēn', '王', '9', '玉结构', '⒈宝贝，宝物～宝。奇～异宝。', '人+彡');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('珑', 'lónɡ', '王', '9', '玉结构', ' 同本义    珑,祷旱玉,龙文。', '龙');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('珠', 'zhū', '王', '10', '玉结构', '⒉样子像珍珠的东西水～。露～儿。眼～子。', '朱');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('班', 'bān', '王', '10', '王结构', '5年格鲁派领袖罗桑却吉坚赞始称班禅（班禅四世）。', '刂+王');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('球', 'qiú', '王', '11', '玉结构', '⒈圆形的立体物～体。圆～。', '求');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('理', 'lǐ', '王', '11', '玉结构', '⒈条纹。条理纹～。条～。有条有～。', '里');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('琴', 'qín', '王', '12', '玉结构', '⒈拨弦乐器，俗称"古琴"。有五根弦，后增加为七根。', '玉+今');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('瑕', 'xiá', '王', '13', '玉结构', '   同本义    瑕,玉小赤也。', '叚');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('瑞', 'ruì', '王', '13', '玉结构', '⒈迷信者所谓的"吉凶预兆"自己认为是嘉～，就是嘉～。', '耑');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('瑟', 'sè', '王', '13', '玉结构', '⒈拨弦乐器之一，一般有二十五根弦。', '必');
