INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('瑶', 'yáo', '王', '14', '玉结构', '⒈美玉，像玉的美石。', '爪+缶');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('璃', 'lí', '王', '14', '玉结构', '⒉   璃lí 1.见"琉璃"。', '离');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('璧', 'bì', '玉', '18', '辟结构', '   同本义    璧,瑞玉环也。', '玉');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('瓣', 'bàn', '瓜', '19', '辛结构', '瓣〈名〉   (形声。', '瓜+辛');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('瓦', 'wǎ', '瓦', '4', '独体结构', '⒈覆盖屋顶的东西，多用陶土烧成，也有用塑料、石棉、水泥等制成的盖上～。～房五间。', '');
