INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('粒', 'lì', '米', '11', '米结构', '⒈小颗的，小碎块的米～。谷～。弹～。盐～儿。', '立');
