INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('纸', 'zhǐ', '纟', '7', '丝结构', '⒈用于书写、印刷、绘画、包装等的东西（多用植物纤维制成）～张。', '氏');
