INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('线', 'xiàn', '纟', '8', '丝结构', '⒈棉、麻、丝、毛、锦纶或金属等制成的细长东西棉～。丝～。毛～。电～。尼龙～。', '戋');
