INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('罩', 'zhào', '罒', '13', '网结构', '⒈捕鱼用的竹笼，也指养鸡的笼子渔～。鸡～子。', '卓');
