INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('羊', 'yánɡ', '羊', '6', '丷结构', '⒈哺乳动物，反刍类。', '三+丨');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('美', 'měi', '羊', '9', '羊结构', '⒈好，善～好。～丽。味～。价廉物～。', '大');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('羞', 'xiū', '羊', '10', '羊结构', '⒈害臊，难为情，使难为情～怯。～人答答。别～她。', '丿+丑');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('羡', 'xiàn', '羊', '12', '羊结构', '⒈爱慕，喜爱而希望得到～慕。临河而～鱼。', '次');
