INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('羽', 'yǔ', '羽', '6', '习结构', '⒈鸟翅膀上的长毛～翼。〈引〉鸟或昆虫的翅膀振～飞翔。泛指鸟的毛～毛未丰。', '习');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('翁', 'wēnɡ', '羽', '10', '公结构', '⒈父亲我～。', '羽');
