INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('肌', 'jī', '月', '6', '肉结构', '   同本义(先秦时期,肌”表示人的肉;肉”表示禽兽的肉)    肌,肉也。', '几');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('肚', 'dù', '月', '7', '肉结构', '   同本义    物体突起或中间鼓出的部分    指思维器', '土');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('肝', 'ɡān', '月', '7', '肉结构', '⒈肝脏，人和高等动物重要器官之一。', '干');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('肠', 'chánɡ', '月', '7', '月结构', '消化器官的一部分，形状像管子，上端连胃，下端通肛门。', '弓+丿+丿');
