INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('肥', 'féi', '月', '8', '肉结构', '⒈含脂肪多，跟"瘦"相对～胖。～肉太多。〈引〉粗，茁壮新枝～嫩。', '巴');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('肩', 'jiān', '月', '8', '戶结构', '⒈肩膀，颈项旁边胳膊上边的部分比（并）～而行。', '肉');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('肯', 'kěn', '月', '8', '止结构', '⒈愿意他～帮助人。只要～努力，就能成功。', '肉');
