INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('脱', 'tuō', '月', '11', '肉结构', '⒈离开，落掉～离。～去。～落。～掉。～粒。～皮。～节。～身。～逃。', '兑');
