INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('脾', 'pí', '月', '12', '肉结构', '⒈脾脏，人和动物内脏之一。暗红色，它是淋巴器官，也是贮血的场所。人的脾脏在腹腔左...', '卑');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('腊', 'là', '月', '12', '肉结构', '⒈干肉，将肉晾干。', '昔');
