INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('腭', 'è', '月', '13', '肉结构', '同本义    余循龟之南,见其腭中沸水,其上唇覆出,为人击缺。', '咢');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('腮', 'sāi', '月', '13', '肉结构', '颊    莲花泛水,艳如越女之腮。', '思');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('腰', 'yāo', '月', '13', '肉结构', '⒈身体的中部，胁下胯上的部分～部。弯～。', '要');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('腹', 'fù', '月', '13', '肉结构', '⒈肚子。躯干的一部分，在胸部之下～部。～直肌。～背（前后）受敌。', '复');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('腾', 'ténɡ', '月', '13', '肉结构', '⒈跳跃虎～。～跃。', '丷+夫+马');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('腿', 'tuǐ', '月', '13', '肉结构', '⒈胫部，股部，下肢小～。大～。脚～。', '退');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('膀', 'bǎnɡ', '月', '14', '肉结构', '1.见"膀子吊"。', '旁');
