INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('膛', 'tánɡ', '月', '15', '肉结构', '⒈胸腔，体腔胸～。开～破肚。', '堂');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('膝', 'xī', '月', '15', '肉结构', ' 大腿和小腿相连关节的前部。', '桼');
