INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('臂', 'bì', '月', '17', '肉结构', '8颈神经的前支和第1胸神经的前支组成，分布在上肢的皮肤、肌肉及胸、背、肩带的肌肉...', '辟');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('臣', 'chén', '臣', '6', '巨结构', '⒈奴隶社会称男性奴隶。', '丨+丨');
