INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('轻', 'qīnɡ', '车', '9', '车结构', '⒈份量小，跟"重"相对这张桌子较～。～于鸿毛。', '圣');
