INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('远', 'yuǎn', '辶', '7', '辵结构', '⒈空间或时间的距离长，跟"近"相对～方。～古。路～。长～。久～。', '袁');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('违', 'wéi', '辶', '7', '辵结构', '⒈背，反，不遵守～背。～反。～犯。～法。不～农时。', '韦');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('连', 'lián', '辶', '7', '辵结构', '⒈连接，相接～年丰收。两岸～山。〈引〉连续～夜（夜间不休息）工作。烽火～三月。', '车');
