INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('配', 'pèi', '酉', '10', '酉结构', '⒈两性结合婚～。～偶（也指夫或妻）。', '己');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('酒', 'jiǔ', '酉', '10', '水结构', '⒈用粮食（高粱、麦、米等）或水果等发酵制成的含乙醇的饮料，有刺激性，多饮会中毒白...', '酉');
