INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('醒', 'xǐnɡ', '酉', '16', '酉结构', '⒈睡完觉或未睡着睡～了。还～着。', '星');
