INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('门', 'mén', '门', '3', '丶结构', '⒈建筑物的进出口，设在进出口能开关的装置，泛指进出口前～。城～。洞～。飞机～。', '丨+㇆');
