INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('陵', 'línɡ', '阝', '10', '阜结构', '⒈大土山丘～。〈引〉坟墓中山～。十三～。', '夌');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('陶', 'táo', '阝', '10', '阜结构', '⒈用粘土烧制的器物～器。～俑。', '匋');
