INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('隆', 'lónɡ', '阝', '11', '阜结构', '⒈高～起。～土。', '夂+生');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('随', 'suí', '阝', '11', '阜结构', '⒈跟着，沿着，顺着～着。跟～。～波逐流。', '迶');
