INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('隔', 'ɡé', '阝', '12', '阜结构', '⒈拦断，互不接触，分开～离。～开。～靴搔痒（〈喻〉不中肯，不贴切，徒劳无功）。', '鬲');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('隙', 'xì', '阝', '12', '阜结构', '⒈裂缝缝～。墙～。', '小+日+小');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('障', 'zhànɡ', '阝', '13', '阜结构', '⒈阻隔，阻碍～碍。一叶～目。', '章');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('难', 'nán', '隹', '10', '又结构', '⒈灾患灾～。患～。遭～。', '隹');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('雀', 'què', '隹', '11', '少结构', '⒈鸟的一类，体小，翼长，嘴呈圆锥状，雌雄羽毛颜色多不相同，吃粮食种子也吃昆虫。', '隹');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('雁', 'yàn', '隹', '12', '厂结构', '   鸟类的一属,', '人+隹');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('雄', 'xiónɡ', '隹', '12', '厷结构', '⒈公的，跟"雌"相对～鸡。～性。～花。', '隹');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('雅', 'yǎ', '隹', '12', '牙结构', '⒈正确的，规范的察纳～言。～乐（原本是西周时的宫廷音乐，后来泛指官方音乐）。～声...', '隹');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('集', 'jí', '隹', '12', '隹结构', '⒈聚，合，会合，总合～中。～聚。～会。～合。聚～。～腋成裘。', '木');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('雇', 'ɡù', '隹', '12', '户结构', '⒈出钱叫人为自己做事～工。～店员。～保姆。', '隹');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('雕', 'diāo', '隹', '16', '周结构', '5世纪出现的拓印碑石的方法。', '隹');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('雨', 'yǔ', '雨', '8', '一结构', '雨,从云层中降向地面的水    雨,濡物者也。', '冂+丨+丶+丶+丶+丶');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('雪', 'xuě', '雨', '11', '雨结构', '⒈从天上落下的白色结晶物，它是高空水汽在摄氏零度以下凝结而成的～兆丰年。万里～飘...', '彐');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('零', 'línɡ', '雨', '13', '雨结构', '⒈落，衰落，雕落～涕。～落。雕～。', '令');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('雷', 'léi', '雨', '13', '雨结构', '⒈云层放电时发出的巨响～声。～电交加。   却相同两份答卷～同。', '田');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('雹', 'báo', '雨', '13', '雨结构', ' 同本义    阳之专气为雹。', '包');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('雾', 'wù', '雨', '13', '雨结构', '⒈飘浮在近地面空气中的大量小水滴或冰晶，主要是水蒸气遇冷后凝结而成大～弥江。', '务');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('需', 'xū', '雨', '14', '雨结构', '⒈要求，应该有，必须有～要。～求。必～品。按～分配。', '而');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('霄', 'xiāo', '雨', '15', '雨结构', '⒈云气云～。', '肖');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('震', 'zhèn', '雨', '15', '雨结构', '⒈雷～电。', '辰');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('霉', 'méi', '雨', '15', '雨结构', '⒈霉菌，真菌的一类，体呈丝状，常寄生或腐生，以孢子繁殖，有毛～、青～、曲～等多种...', '母');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('霎', 'shà', '雨', '16', '雨结构', '⒈小雨。', '妾');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('霜', 'shuānɡ', '雨', '17', '雨结构', '⒈地面上或近地面的水汽冷至摄氏零度以下凝结而成微细冰粒，附着于物体上有～。', '相');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('霞', 'xiá', '雨', '17', '雨结构', ' 同本义    霞,赤云气也。', '叚');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('露', 'lù', '雨', '21', '雨结构', '⒈显现，用于一些口语～脸。～马脚。', '路');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('青', 'qīnɡ', '青', '8', '丰结构', '⒈颜色   ①深蓝色～天。', '月');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('静', 'jìnɡ', '青', '14', '青结构', '⒈停止的，跟"动"相对～止。树欲～而风不止。', '争');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('非', 'fēi', '非', '8', '三结构', '⒈不， 不是，不对，越出，不合理。', '丿+丨+三');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('靠', 'kào', '非', '15', '告结构', '⒈倚着，挨近，接近倚～。～在壁上。～近点。', '非');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('面', 'miàn', '面', '9', '一结构', '⒈脸，头的前部～孔。颜～。～不改色。', '丶+囬');
