INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('顶', 'dǐnɡ', '页', '8', '丁结构', '   同本义    顶颠也。', '页');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('项', 'xiànɡ', '页', '9', '工结构', '⒈颈子的后部。泛指颈部～背。屈～。引～高歌。', '页');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('顺', 'shùn', '页', '9', '川结构', '⒈向着同一个方向，跟"逆"相对～水。～应。～风而呼。～于民心。', '页');
