INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('顽', 'wán', '页', '10', '元结构', '⒈愚蠢无知愚～。痴～。笨～。', '页');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('顾', 'ɡù', '页', '10', '厄结构', '⒈回头看瞻前～后。〈引〉看左～右盼。环～四周。', '页');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('顿', 'dùn', '页', '10', '屯结构', '1.见"冒顿"。', '页');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('预', 'yù', '页', '10', '予结构', '⒈在先，事前～先。～告。～言。～计。～约。～定。～防。～祝胜利。', '页');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('领', 'lǐnɡ', '页', '11', '令结构', '⒈脖子引～北望。', '页');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('颇', 'pō', '页', '11', '皮结构', '⒈偏，偏差偏～。', '页');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('颈', 'jǐnɡ', '页', '11', '圣结构', '⒈俗称"脖子"，头与躯干相连的部分引～高歌。', '页');
