INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('食', 'shí', '食', '9', '人结构', '⒈供养，拿东西给人吃～亲（亲父母）尽孝。   食shí   ⒈吃～菜。～鱼。废寝...', '良');
