INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('饭', 'fàn', '饣', '7', '食结构', '⒈熟的谷物食品，多指大米饭这～好吃。这～好香哟！', '反');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('饮', 'yǐn', '饣', '7', '食结构', '⒈喝～茶。～酒。～水思源。水浊不可～。', '欠');
