INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('饶', 'ráo', '饣', '9', '食结构', '⒈多，富足～有兴趣。～舌（多话）。物产富～。', '尧');
