INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('饿', 'è', '饣', '10', '食结构', '   同本义    饿,饥也。', '我');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('馆', 'ɡuǎn', '饣', '11', '食结构', '⒈接待宾客或旅客居住或食宿的房屋宾～。旅～。', '官');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('首', 'shǒu', '首', '9', '丷结构', '⒈头～饰。昂～阔步。俯～帖耳。', '一+丶+目');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('香', 'xiānɡ', '香', '9', '禾结构', '⒈气味好闻，味道鲜美，跟"臭"相对～气。～花。稻谷～。饭菜～。', '日');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('马', 'mǎ', '马', '3', '独体结构', '⒈家畜。耳小直立，面长，颈上缘有鬃，尾巴有长毛，四肢强健，善跑，供人骑或拉东西等...', '');
