INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('驰', 'chí', '马', '6', '马结构', '⒈奔跑，使劲赶马。〈引〉车马疾行奔～。～骋。疾～。特指驱马进击将～之。', '也');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('驱', 'qū', '马', '7', '马结构', '⒈赶马。〈引〉赶，赶走～马。～虫。～逐。～车前进。', '区');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('驶', 'shǐ', '马', '8', '马结构', '⒈马快跑，跑疾～。奔～。', '史');
