INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('驼', 'tuó', '马', '8', '马结构', '⒈骆驼。', '它');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('驾', 'jià', '马', '8', '加结构', '⒈把车或农具等套在牲口身上～车。～轻就熟（〈喻〉做很熟悉的事）。', '马');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('骂', 'mà', '马', '9', '口结构', '⒈用粗野的话侮辱人辱～。莫～人。', '口+马');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('骄', 'jiāo', '马', '9', '马结构', '⒈马高大健壮的样子四牡有～（牡公马）。', '乔');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('骆', 'luò', '马', '9', '马结构', '⒉   骆jià 1.见"骆田"。', '各');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('验', 'yàn', '马', '10', '马结构', '⒈检查，察看～血。～光。～收。～证。', '佥');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('骏', 'jùn', '马', '10', '马结构', '⒈好马～马。八～日行三万里。〈引〉急速～奔。', '夋');
