INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('骗', 'piàn', '马', '12', '马结构', '⒈欺蒙，说假话欺～。～人。', '扁');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('骚', 'sāo', '马', '12', '马结构', '⒈动乱，扰乱，不安定～动。～乱。～扰。', '蚤');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('骤', 'zhòu', '马', '17', '马结构', '⒈马奔驰弛～。〈引〉急速，快速暴风～雨。', '聚');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('骨', 'ɡǔ', '骨', '9', '独体结构', '⒊见gū、gú。   骨gǔ   ⒈骨头，脊椎动物体内支持身体的坚硬组织肋～。股...', '');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('高', 'ɡāo', '高', '10', '亠结构', '⒈跟"低"相对   ①由下至上距离大的，离地面远的～山。', '口+冂+口');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('鬼', 'ɡuǐ', '鬼', '9', '丶结构', '⒈迷信者认为"人死后有灵魂"叫"鬼"没有～也没有神。物死不能为～，人死何故独能为...', '田+儿+厶');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('魁', 'kuí', '鬼', '13', '鬼结构', '⒈头目，首领他是～首。罪～祸首。～甲（状元）。', '斗');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('魂', 'hún', '鬼', '13', '云结构', '   同本义    魂,阳气也。', '鬼');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('魄', 'pò', '鬼', '14', '白结构', '⒉精神，精力，气概～力。', '鬼');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('魏', 'wèi', '鬼', '17', '委结构', '1年被晋献公攻灭,把它封给毕万   战国七雄之一。', '鬼');
