INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('鱼', 'yú', '鱼', '8', '刀结构', '   完全水生并在水中呼吸的有头冷血脊椎动物,', '田+一');
INSERT OR IGNORE INTO character_info (char, pinyin, radical, strokes, structure, meaning, decompose) VALUES ('鲁', 'lǔ', '鱼', '12', '鱼结构', '⒈笨，愚钝～钝。', '日');
